import {api,jobs} from './data.js';
import {availabilityLabel,jobLabel,phrase,statusLabel} from './i18n.js';
const app=document.querySelector('#app'),uk=document.body.dataset.site==='ukr',admin=document.body.dataset.site==='admin';
let lang='nl';try{if(!uk&&localStorage.getItem('uhr-lang')==='en')lang='en'}catch{}
const tr=key=>phrase(lang,key),jobName=name=>jobLabel(lang,name),statusName=name=>statusLabel(lang,name),availName=name=>availabilityLabel(lang,name);
function applyLang(){if(uk)return;document.documentElement.lang=lang;document.title=lang==='en'?'UHR — Tradespeople for construction':'UHR — Vakmensen voor de bouw'}
applyLang();
const workers=await api.workers();
let requests=[],companyProfile=null;
const state={favorites:new Set(),picks:new Set(),wizard:0,form:{},files:{},submitted:null,messages:[],approved:new Set(),filter:{},account:null,authConfig:{},sna:null,snaBusy:false};
async function companyApi(path,options={}){const response=await fetch('/api/v1/company/'+path,{...options,headers:typeof options.body==='string'?{'Content-Type':'application/json'}:{}});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:'Controleer de ingevulde gegevens en probeer het opnieuw.');return data}
async function loadCabinet(){if(uk||admin||state.account?.company?.status!=='approved'){requests=[];state.favorites=new Set();state.picks=new Set();companyProfile=null;return}try{const [data,favs,prof,picked]=await Promise.all([companyApi('requests'),companyApi('favorites'),companyApi('profile'),companyApi('picks').catch(()=>({ids:[]}))]);requests=data.items||[];state.favorites=new Set(favs.ids||[]);state.picks=new Set(picked.ids||[]);companyProfile=prof}catch(error){toast(error.message)}}
if(!uk&&!admin){[state.account,state.authConfig]=await Promise.all([companyApi('me').catch(()=>null),companyApi('auth/config').catch(()=>({}))]);await loadCabinet()}
const avatar=(w,large=false)=>`<img class="provider-avatar ${w.providerType==='company'?'company':'individual'} ${large?'large':''}" src="${new URL('./images/'+w.avatar,import.meta.url).href}" alt="${w.providerType==='company'?tr('logo.company'):tr('logo.person')}" loading="lazy"/>`;
const art=(job,cls='')=>{const names={Timmerman:'carpenter',Elektricien:'electrical',Kabelmonteur:'cable',Schilder:'finishing',Lasser:'welder',Tegelzetter:'tiler',Loodgieter:'plumber',Grondwerker:'groundworker',Betonwerker:'concrete','Allround vakman':'allround'};return names[job]?`<img class="trade-art ${cls}" src="${new URL('./images/'+names[job]+'.png',import.meta.url).href}" alt=""/>`:icon(({Lasser:'wrench',Tegelzetter:'grid-2x2',Loodgieter:'wrench',Grondwerker:'shovel',Betonwerker:'brick-wall','Allround vakman':'hammer'})[job]||'hammer')};
const photo='https://images.unsplash.com/photo-1504307651254-35680f356dfd?auto=format&fit=crop&w=1100&q=85';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nlDate=v=>{const [y,m,d]=String(v||'').split('-');return d?`${d}-${m}-${y}`:'—'};
const icon=(name)=>'<i data-lucide="'+name+'" aria-hidden="true"></i>';
const icons=()=>window.lucide?.createIcons({attrs:{'stroke-width':1.7,'aria-hidden':'true'}});
const btn=(text,href,cls='')=>`<a class="btn ${cls}" href="#${href}">${text}</a>`;
const brand=()=>`<a href="#home" class="brand">${uk?'<span class="mark">↗</span>':`<img src="./assets/logo.png" alt=""/>`}${uk?'Ukrwerkspot':'UHR'}${admin?' · Admin':''}</a>`;
const demo=()=>'';
const langSelect=()=>uk?`<select class="language" aria-label="Мова"><option>Українська</option><option>EN</option><option>Nederlands</option></select>`:`<select class="language" aria-label="${tr('lang.label')}"><option value="nl" ${lang==='nl'?'selected':''}>NL</option><option value="en" ${lang==='en'?'selected':''}>EN</option></select>`;
const header=()=>`${demo()}<div class="wrap"><header class="header">${brand()}<nav class="nav">${uk?'<a href="#home/how">Як це працює</a><a href="#home/benefits">Для майстрів</a><a href="#faq">Поширені запитання</a>':`<a href="#home/benefits">${tr('nav.clients')}</a><a href="#catalog">${tr('nav.trades')}</a><a href="#home/how">${tr('nav.how')}</a><a href="#about">${tr('nav.about')}</a><a href="#contact">${tr('nav.contact')}</a>`}${langSelect()}${uk?btn('Заповнити анкету','register'):btn(state.account?tr('nav.account'):tr('nav.login'),'login','light')+btn(tr('nav.register'),'register')}</nav></header></div>`;
const footer=()=>`<div class="wrap"><footer class="footer">${brand()}<div class="links"><a href="#contact">${uk?'Контакти':tr('nav.contact')}</a><a href="#privacy">${uk?'Конфіденційність':tr('footer.privacy')}</a><a href="#terms">${uk?'Умови використання':tr('footer.terms')}</a><a href="#cookies">${uk?'Cookiebeleid':tr('footer.cookies')}</a><a href="#faq">FAQ</a></div><span>© 2026 ${uk?'Ukrwerkspot':'UHR'}</span></footer></div>`;
function landing(){const benefits=uk?['Перевірені замовники','Захист особистих контактів','Пропозиції за спеціалізацією','Підтримка менеджера','Ваш досвід має значення','Без відкритої публікації даних']:['benefit.1','benefit.2','benefit.3','benefit.4','benefit.5','benefit.6'].map(tr);const steps=uk?['Заповніть анкету','Додайте документи та роботи','Ми перевіримо ваш профіль','Отримуйте пропозиції']:['step.1','step.2','step.3','step.4'].map(tr);return `${header()}<main><div class="wrap"><section class="hero"><div><div class="eyebrow">${uk?'Українська майстерність. Нідерландські можливості.':'Ukrainian expertise. Dutch ambition.'}</div><h1>${uk?'Ваша майстерність.<br>Наші можливості.<br><span>Спільне майбутнє.</span>':tr('hero.title')}</h1><p>${uk?'Працюєте у будівельній сфері в Нідерландах? Приєднуйтесь до бази перевірених майстрів. Заповніть профіль та отримуйте пропозиції через нашого менеджера.':tr('hero.lead')}</p><div class="actions">${btn(uk?'Заповнити анкету ↗':tr('hero.cta'),uk?'register':'catalog')}${btn(uk?'Як це працює':tr('hero.register'),uk?'home/how':'register','light')}</div><div class="trust"><span>✓ ${uk?'Перевірка VCA':tr('hero.vca')}</span><span>✓ ${uk?'Особистий менеджер':tr('hero.contact')}</span></div></div><div class="visual"><img src="${photo}" alt="${uk?'Будівельні роботи на об’єкті':tr('hero.photo')}"/><div class="float-card"><div><strong>${uk?'01':workers.length}</strong><small>${uk?'Анкета — перший крок':tr('hero.available')}</small></div><div><strong>VCA ✓</strong><small>${uk?'Безпека та професійність':tr('hero.certs')}</small></div><div><strong>NL</strong><small>${uk?'Працюємо по всій країні':tr('hero.coverage')}</small></div></div></div></section><div class="strip"><span>${uk?'Майстерність без кордонів':tr('hero.partner')}</span><span>KVK · VCA · ${uk?'Підтримка українською':tr('hero.guidance')}</span></div></div><section class="section cream" id="benefits"><div class="wrap"><div class="section-head"><div><div class="eyebrow">${uk?'Спокій та впевненість':tr('why.eyebrow')}</div><h2>${uk?'Ви працюєте. Ми підтримуємо.':tr('why.title')}</h2></div><p>${uk?'Більше часу для того, що ви вмієте найкраще.':tr('why.lead')}</p></div><div class="grid">${benefits.map((b,i)=>`<article class="card"><div class="icon">${icon(['shield-check','lock-keyhole','map-pin','handshake','calendar-check','user-check'][i])}</div><h3>${b}</h3><p>${uk?['Ми перевіряємо компанії перед співпрацею.','Контакти доступні лише вашому менеджеру.','Ваш досвід допомагає знайти відповідний проєкт.','Поруч на кожному етапі співпраці.','Покажіть сертифікати та приклади робіт.','У каталозі — лише професійна інформація.'][i]:tr('benefit.'+(i+1)+'p')}</p></article>`).join('')}</div></div></section>${!uk?`<section class="section wrap"><div class="section-head"><div><div class="eyebrow">${tr('spec.eyebrow')}</div><h2>${tr('spec.title')}</h2></div>${btn(tr('spec.all'),'catalog','light')}</div><div class="grid profession-grid">${jobs.map((j)=>`<a class="card" href="#catalog/${j}"><div class="category-art">${art(j)}</div><h3>${jobName(j)} ↗</h3><span class="muted">${workers.filter(w=>w.job===j).length} ${tr('spec.profiles')}</span></a>`).join('')}</div></section>`:''}<section class="section wrap" id="how"><div class="eyebrow">${uk?'Лише кілька простих кроків':tr('how.eyebrow')}</div><h2>${uk?'Від анкети до нового проєкту.':tr('how.title')}</h2><div class="steps">${steps.map((s,i)=>`<div class="step"><b>0${i+1}</b><h3>${s}</h3><p>${uk?'Зрозумілий процес із підтримкою менеджера.':tr('how.note')}</p></div>`).join('')}</div><div class="note">◇ ${uk?'Ваші особисті контакти не публікуються. Спілкування із замовниками відбувається через менеджера.':tr('how.protected')}</div></section><section class="wrap section"><div class="callout"><div><h2>${uk?'Зробіть наступний крок.':tr('cta.title')}</h2><p>${uk?'Розкажіть про свій досвід — ми допоможемо знайти можливості.':tr('cta.text')}</p></div>${btn(uk?'Заповнити анкету ↗':tr('cta.button'),'register','lime')}</div></section></main>${footer()}`}
const menuItems=()=>[['overview','menu.overview'],['catalog','menu.trades'],['favorites','menu.favorites'],['requests','menu.requests'],['messages','menu.messages'],['orders','menu.orders'],['company','menu.company'],['documents','menu.documents'],['settings','menu.settings']].map(([id,key])=>[id,'',tr(key)]);
function shell(content,page){const items=admin?[["overview","layout-dashboard","Огляд"],["masters","users","Анкети майстрів"],["companies","building-2","Компанії"],["requests","clipboard-list","Заявки"],["messages","messages-square","Повідомлення"]]:menuItems();const names={overview:"layout-dashboard",catalog:"users",favorites:"heart",requests:"list-checks",messages:"messages-square",orders:"clipboard-list",company:"building-2",documents:"files",settings:"settings"};const link=([id,,label])=>`<a class="${page===id?"active":""}" ${page===id?'aria-current="page"':""} href="#${id}">${icon(names[id]||"users")}${label}</a>`;return `${demo()}<div class="workspace"><header class="workspace-header"><div class="workspace-nav">${brand()}<nav aria-label="${admin?'Адмінка':tr('shell.workspace')}">${items.slice(0,5).map(link).join("")}</nav>${admin?"":langSelect()}<details class="account-menu"><summary>${icon("building-2")}<span>${admin?"Менеджер":tr('menu.mine')}</span>${icon("chevron-down")}</summary><div class="dropdown">${items.slice(5).map(link).join("")}<a href="#home" ${admin?'':'data-logout'}>${icon("log-out")}${admin?"До сайтів":tr('menu.logout')}</a></div></details></div></header><main class="content"><div class="topbar"><span>${admin?"Спільна адмінка · Ukrwerkspot + UHR":tr('shell.workspace')+" / "+(items.find(x=>x[0]===page)?.[2]||tr('shell.profile'))}</span><span>${admin?"Менеджернстрація":esc(companyProfile?.company_name||tr('menu.mine'))+" · "+tr('shell.verified')}</span></div>${content}</main></div>`}
const placeText=w=>esc(w.radius?`${w.region} · ${w.radius} km`:w.region);
const yearsText=w=>w.years?`${w.years} ${tr('card.years')}`:tr('card.yearsAsk');
const rateText=w=>w.rate?`€ ${w.rate}`:tr('card.rateAsk');
const certText=w=>esc(w.cert.join(' · ')||tr('card.certs'));
function pickButton(w,labeled=false){const on=state.picks.has(w.id);return `<button type="button" data-pick="${w.id}" class="pick${on?" saved":""}${labeled?" labeled":""}" aria-label="${tr('card.select')}" aria-pressed="${on}">${icon(on?"check":"square")}${labeled?`<span>${tr('card.select')}</span>`:""}</button>`}
function favButton(w,labeled=false){const on=state.favorites.has(w.id);return `<button type="button" data-fav="${w.id}" class="favorite${on?" saved":""}${labeled?" labeled":""}" aria-label="${tr('card.favorite')}" aria-pressed="${on}">${icon("heart")}${labeled?`<span>${tr('profile.save')}</span>`:""}</button>`}
function workerCard(w){return `<article class="worker-row"><div class="worker-identity">${avatar(w)}<div><span class="muted">${w.providerType==='company'?tr('card.company'):tr('card.person')} #${w.id}</span><a href="#profile/${w.id}"><h3>${esc(jobName(w.job))}</h3></a><span class="provider-kind">${w.providerType==='company'?tr('card.firm'):tr('card.self')}</span><span class="badge ${w.available==='Direct beschikbaar'?'':'yellow'}">${esc(availName(w.available))}</span></div></div><div class="worker-facts"><span>${icon("map-pin")} ${placeText(w)}</span><span>${icon("clock")} ${yearsText(w)}</span><span>${icon("shield-check")} ${certText(w)}</span></div><div class="worker-price"><strong>${rateText(w)}</strong><small>${w.rate?tr('card.perHour'):tr('card.rateVia')}</small></div><div class="row-actions">${btn(tr('card.view'),"profile/"+w.id,"light")}${pickButton(w)}${favButton(w)}</div></article>`}
function overview(){return shell(`<div class="section-head"><div><div class="eyebrow">${tr('home.eyebrow')}</div><h1>${tr('home.welcome')}${companyProfile?.contact_name?', '+esc(companyProfile.contact_name):''}.</h1><p>${tr('home.lead')}</p></div>${btn(tr('home.search'),'catalog')}</div><div class="stats">${[[tr('home.stat.people'),workers.length,tr('home.stat.peopleNote')],[tr('home.stat.requests'),requests.filter(x=>!['Afgerond','Geannuleerd'].includes(x.status)).length,tr('home.stat.requestsNote')],[tr('home.stat.messages'),requests.reduce((n,r)=>n+(r.manager_messages||0),0),tr('home.stat.messagesNote')],[tr('home.stat.favorites'),state.favorites.size,tr('home.stat.favoritesNote')]].map(([a,b,c])=>`<div class="card">${a}<strong>${b}</strong>${c}</div>`).join('')}</div><div class="section-head"><h3>${tr('home.recent')}</h3><a href="#messages">${tr('home.allRequests')}</a></div>${requestTable()}<div class="section-head" style="margin-top:35px"><h3>${tr('home.next')}</h3>${btn(tr('home.allTrades'),'catalog','light')}</div><div class="cards">${workers.slice(0,2).map(workerCard).join('')}</div><div class="note">${tr('home.activity')}</div>`,'overview')}
function catalog(favorites=false,job=""){const jobOpts=[["",tr('filter.allTrades')],...jobs.map(j=>[j,jobName(j)])];const regionOpts=[["Heel Nederland",tr('filter.allNl')],...[...new Set(workers.map(w=>w.region))]];return shell(`<div class="section-head"><div><div class="eyebrow">${tr('catalog.eyebrow')}</div><h1>${favorites?tr('catalog.favorites'):tr('catalog.title')}</h1><p>${tr('catalog.lead')}</p></div><span class="catalog-view">${icon("list")} ${tr('catalog.view')}</span></div><div class="catalog"><div class="filter-toolbar"><div class="search-control">${icon("search")}<input class="search" id="search" placeholder="${tr('catalog.search')}" aria-label="${tr('catalog.searchLabel')}"/></div><button class="btn light" data-filter-toggle aria-expanded="false" aria-controls="catalog-filters">${icon("sliders-horizontal")} ${tr('catalog.filters')}</button></div><div class="filters" id="catalog-filters"><div class="filter-heading"><h3>${tr('catalog.refine')}</h3><button data-reset class="btn light">${icon("rotate-ccw")} ${tr('catalog.clear')}</button></div><div class="filter-fields">${select(tr('filter.trade'),"job",jobOpts,job)}${select(tr('filter.location'),"region",regionOpts)}${select(tr('filter.radius'),"radius",[["Alle afstanden",tr('filter.allRadius')],["50","50"],["70","70"],["100","100"]])}<label>${tr('filter.rate')}<input id="rate" type="number" min="1" placeholder="${tr('filter.ratePh')}"/></label>${select(tr('filter.years'),"years",[["Alle ervaring",tr('filter.allYears')],["5","5"],["10","10"],["15","15"]])}${select(tr('filter.available'),"available",[["Alle",tr('filter.all')],["Direct beschikbaar",availName("Direct beschikbaar")]])}${select(tr('filter.cert'),"cert",[["Alle certificaten",tr('filter.allCerts')],["VCA","VCA"]])}</div><button class="btn filter-done" data-filter-toggle>${tr('catalog.done')}</button></div><div class="results-heading"><p id="result-count" class="muted" aria-live="polite"></p><span class="muted">${tr('catalog.sorted')}</span></div><div class="cards worker-list" id="worker-results" data-favorites="${favorites}"></div></div>`,favorites?"favorites":"catalog")}
function select(label,id,opts,value=''){return `<label>${label}<select id="${id}" name="${id}">${opts.map(item=>{const pair=Array.isArray(item),v=pair?String(item[0]):String(item),text=pair?item[1]:item;return `<option value="${esc(v)}" ${(value||state.form[id]||'')===v?'selected':''}>${esc(text)}</option>`}).join('')}</select></label>`}
function filterCards(){const target=document.querySelector('#worker-results');if(!target)return;const val=id=>document.getElementById(id)?.value||'';const search=val('search').toLowerCase();const list=workers.filter(w=>(target.dataset.favorites!=='true'||state.favorites.has(w.id))&&`${w.job} ${jobName(w.job)} ${w.region} ${w.id}`.toLowerCase().includes(search)&&(!val('job')||w.job===val('job'))&&(val('region')==='Heel Nederland'||w.region===val('region'))&&(!val('rate')||(w.rate&&w.rate<=Number(val('rate'))))&&(!Number(val('years'))||w.years>=Number(val('years')))&&(!Number(val('radius'))||(w.radius&&w.radius<=Number(val('radius'))))&&(val('available')!=='Direct beschikbaar'||w.available==='Direct beschikbaar')&&(val('cert')==='Alle certificaten'||w.cert.some(c=>c.includes(val('cert')))));target.innerHTML=list.map(workerCard).join('')||`<div class="card empty">${tr('catalog.empty')}</div>`;icons();document.querySelector('#result-count').textContent=tr('catalog.found').replace('%s',list.length);}
function profile(id){const w=workers.find(w=>w.id===Number(id));if(!w)return info("404");return shell(`<a href="#catalog" class="back-link">${icon("arrow-left")} ${tr('profile.back')}</a><section class="profile-hero"><div><div class="eyebrow">${tr('card.person')} #${w.id} · ${tr('profile.checked')}</div><h1>${tr('profile.title')}</h1><h2>${esc(jobName(w.job))} ${tr('profile.in')} ${esc(w.region)}</h2><p>${esc(w.works||tr('profile.fallback'))}</p><div class="actions">${pickButton(w,true)}${favButton(w,true)}</div></div><div class="profile-seal">${avatar(w,true)}<strong>${w.providerType==='company'?tr('card.company'):tr('card.person')} #${w.id}</strong><span>${w.providerType==='company'?tr('card.firm'):tr('card.self')}</span><span class="badge">${esc(availName(w.available))}</span></div></section><div class="profile-metrics"><div><strong>${w.years?w.years+' '+tr('card.yearUnit'):'—'}</strong><span>${tr('profile.experience')}</span></div><div><strong>${esc(w.region)}</strong><span>${w.radius?tr('profile.radius').replace('%s',w.radius):tr('profile.area')}</span></div><div><strong>${w.rate?'€ '+w.rate+tr('profile.hour'):tr('card.rateAsk')}</strong><span>${w.rate?tr('profile.excl'):tr('profile.rateVia')}</span></div><div><strong>${certText(w)}</strong><span>${tr('profile.certs')}</span></div></div><nav class="profile-nav"><a href="#profile/${w.id}" data-section="expertise">${tr('profile.expertise')}</a><a href="#profile/${w.id}" data-section="work">${tr('profile.work')}</a><a href="#profile/${w.id}" data-section="contact">${tr('profile.contact')}</a></nav><section class="profile-section" id="expertise"><div><div class="eyebrow">${tr('profile.expEyebrow')}</div><h2>${tr('profile.expTitle')}</h2></div><div><p>${esc(w.description||tr('profile.descFallback'))}</p><h3>${tr('profile.certsTitle')}</h3>${w.cert.map(c=>`<span class="badge">${icon("shield-check")} ${esc(c)}</span> `).join("")||`<p class="muted">${tr('profile.certsEmpty')}</p>`}</div></section><section class="profile-section work-section" id="work"><div><div class="eyebrow">${tr('profile.workEyebrow')}</div><h2>${tr('profile.workTitle')}</h2><p>${tr('profile.workNote')}</p></div><div class="work-stories">${[tr('profile.work1'),tr('profile.work2')].map((title,i)=>`<article class="work-story"><img src="${photo}" alt="${tr('profile.workPhoto')}" loading="lazy"/><div><span class="muted">${i?tr('profile.newbuild'):tr('profile.renovation')}</span><h3>${title}</h3><p>${tr('profile.workText')}</p></div></article>`).join("")}</div></section><section class="profile-contact" id="contact"><div><div class="eyebrow">${icon("lock-keyhole")} ${tr('profile.lock')}</div><h2>${tr('profile.ask')}</h2><p>${tr('profile.askText')}</p></div>${btn(tr('select.contacts'),"requests")}</section>` ,"catalog")}
function requestTable(){if(!requests.length)return `<div class="card empty">${tr('requests.empty')}</div>`;return `<div class="card table-scroll"><table><thead><tr>${['table.request','table.project','table.trade','table.start','table.status','table.manager'].map(key=>`<th>${tr(key)}</th>`).join('')}</tr></thead><tbody>${requests.map(r=>`<tr data-status="${esc(r.status)}"><td><a href="#request-detail/${r.id}">${esc(r.id)} ↗</a></td><td>${esc(r.project)}</td><td>${esc(jobName(r.job))}</td><td>${esc(nlDate(r.date))}</td><td><span class="badge ${r.status==='In behandeling'?'yellow':''}">${esc(statusName(r.status))}</span></td><td>${tr('table.managerName')}</td></tr>`).join('')}</tbody></table></div>`}
function selectionPage(contact=false){const picked=workers.filter(w=>state.picks.has(Number(w.id))||state.picks.has(w.id));const head=`<div class="section-head"><div><div class="eyebrow">${tr('select.eyebrow')}</div><h1>${tr('select.title')}</h1><p>${tr('select.lead')}</p></div></div>`;if(!picked.length)return shell(head+`<div class="card empty">${tr('select.empty')}</div><div class="actions">${btn(tr('home.allTrades'),'catalog')}</div>`,'requests');if(!contact)return shell(head+`<div class="cards">${picked.map(workerCard).join('')}</div><div class="actions selection-create">${btn(tr('select.create'),'requests/contact')}</div>`,'requests');return shell(`<a href="#requests" class="back-link">${icon("arrow-left")} ${tr('select.title')}</a><form id="selection-form" class="card selection-panel"><div class="eyebrow">${tr('select.orderEyebrow')}</div><h1>${tr('select.orderTitle')}</h1><p>${tr('select.orderLead')}</p><div class="cards">${picked.map(workerCard).join('')}</div><div class="actions"><button class="btn light" name="channel" value="email">${tr('select.email')}</button><button class="btn" name="channel" value="chat">${tr('select.chat')}</button></div></form>`,'requests')}
function ordersPage(){return shell(`<div class="section-head"><div><div class="eyebrow">${tr('orders.eyebrow')}</div><h1>${tr('orders.title')}</h1><p>${tr('orders.lead')}</p></div></div>${requestTable()}`,'orders')}
function requestsPage(){const statuses=['Concept','Ingediend','In behandeling','Kandidaat geselecteerd','Bevestigd','Afgerond','Geannuleerd'];return shell(`<h1>${admin?'Заявки компаній':tr('requests.title')}</h1><p>${admin?'Concept → Ingediend → In behandeling → Kandidaat geselecteerd → Bevestigd → Afgerond / Geannuleerd':tr('requests.flow')}</p><select id="request-status" style="max-width:260px;margin-bottom:20px"><option value="">${tr('requests.all')}</option>${statuses.map(s=>`<option value="${esc(s)}">${esc(statusName(s))}</option>`).join('')}</select>${requestTable()}`,'requests')}
const field=(name,label,type='text',required=true,value,wide=false)=>`<label class="${wide?'full':''}"><span>${label}${required?' *':''}</span><input name="${name}" type="${type}" ${required?'required':''} value="${esc(value??state.form[name])}"/></label>`;
const area=(name,label,required=false,value)=>`<label class="full"><span>${label}${required?' *':''}</span><textarea name="${name}" ${required?'required':''}>${esc(value??state.form[name])}</textarea></label>`;
const upload=(name,label,required=false,multiple=true)=>`<label class="upload full" data-drop><span>↑ ${label}${required?' *':''}</span><input name="${name}" type="file" accept="image/*,.pdf" ${multiple?'multiple':''} ${required&&!state.files[name]?.length?'required':''}/><small class="muted">PDF, JPG, PNG · ${uk?'до 10 MB на файл':tr('file.limit')}</small><div data-files>${esc(state.form[name]||'')}</div></label>`;
const optional=(label,name,opts)=>select(label,name,['—',...opts]);
const NUMERIC=['radius_km','hourly_rate','expected_count'];
const CRAFTSMAN_KEYS=['name','phone','email','profession','works','experience_ua','experience_nl','city','radius_km','hourly_rate','availability','nationwide','company_name','kvk','btw','address','website','instagram','facebook','tiktok','extra_work','description','language','portfolio_url'];
const COMPANY_KEYS=['company_type','company_name','kvk','address','contact_name','contact_role','phone','website','description'];
const FORM_LABELS=uk?{name:'ПІБ',phone:'Телефон',email:'Email',profession:'Вид діяльності',works:'Перелік робіт',experience_ua:'Досвід в Україні',experience_nl:'Досвід у Нідерландах',city:'Місто',radius_km:'Радіус, км',hourly_rate:'Ставка €/год',availability:'Доступність',nationwide:'По всій території Нідерландів',company_name:'Компанія',kvk:'KVK',btw:'BTW',address:'Адреса',website:'Сайт',instagram:'Instagram',facebook:'Facebook',tiktok:'TikTok',extra_work:'Додаткові види робіт',description:'Опис досвіду',language:'Мова спілкування',portfolio_url:'Портфоліо',vca:'VCA',portfolio:'Фото робіт',tools:'Фото інструментів',vehicle:'Фото авто',certificates:'Інші сертифікати',portrait:'Фото в робочому одязі'}:{company_name:'Bedrijf',kvk:'KVK',btw:'BTW',address:'Adres',website:'Website',description:'Opmerking',contact_name:'Contactpersoon',contact_role:'Functie',email:'E-mail',phone:'Telefoon',region:'Werkgebied',desired_profession:'Specialisatie',expected_count:'Aantal vakmensen',sna:'SNA-certificaat',company_docs:'Bedrijfsdocumenten',certificates:'Certificaten'};
function applicationPayload(){const out={};for(const k of uk?CRAFTSMAN_KEYS:COMPANY_KEYS){let v=state.form[k];if(v===undefined||v===''||v==='—')continue;if(NUMERIC.includes(k))v=Number(v);out[k]=v}return out}
async function shrinkImage(file){if(!file.type.startsWith('image/')||file.type==='image/heic'||file.size<1.5*1024*1024)return file;try{const bitmap=await createImageBitmap(file);const scale=Math.min(1,2000/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.85));return blob?new File([blob],file.name.replace(/\.\w+$/,'')+'.jpg',{type:'image/jpeg'}):file}catch{return file}}
async function submitApplication(){const body=new FormData();body.append('data',JSON.stringify(applicationPayload()));let total=0;for(const [kind,files] of Object.entries(state.files))for(const original of files){const file=await shrinkImage(original);total+=file.size;body.append(kind,file,file.name)}if(total>28*1024*1024)throw new Error(uk?'Файли занадто великі разом. Залиште менше фото.':tr('file.tooBig'));const response=await fetch('/api/v1/public/applications/'+(uk?'craftsmen':'companies'),{method:'POST',body});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:(uk?'Не вдалося надіслати анкету. Спробуйте ще раз.':tr('file.failed')));return data}
function registration(){if(!uk)return companyRegistration();if(state.submitted)return `${header()}<div class="wizard card empty"><div class="icon" style="margin:auto">✓</div><h1>${uk?'Дякуємо! Ваш профіль надіслано на перевірку.':'Uw registratie wordt gecontroleerd.'}</h1><p>${uk?`Анкета № ${esc(state.submitted.id)}. Очікуваний строк перевірки: 2–3 робочі дні. Ми надіслали підтвердження з вашими даними на ${esc(state.form.email)}.`:`Aanvraag #${esc(state.submitted.id)}. Verwachte beoordeling: 2–3 werkdagen. Uw manager neemt contact met u op.`}</p>${btn(uk?'На головну':'Terug naar home','home')}</div>${footer()}`;/* Повна анкета Ukrwerkspot (вимкнена, замість неї коротка нижче):
const names=uk?['Особисті дані','Компанія','Професія','Документи','Перевірка']:['Bedrijf','Contactpersoon','Inzet & documenten','Controle'];
if(uk){if(i===0)body=field('name','Ім’я та прізвище')+field('phone','Телефон','tel')+field('email','Email','email')+select('Мова спілкування','language',['Українська','Nederlands','English'])+upload('portrait','Фото в робочому одязі');if(i===1)body=field('company','Назва компанії')+field('kvk','Номер KVK (8 цифр)')+field('btw','Номер BTW')+field('address','Адреса реєстрації KVK')+field('website','Сайт','url',false)+field('instagram','Instagram','url',false)+field('facebook','Facebook','url',false)+field('tiktok','TikTok','url',false);if(i===2)body=select('Основна спеціалізація','profession',jobs)+field('extra','Додаткові види робіт','text',false)+field('experience','Досвід роботи, років','number')+field('hourly','Ставка €/год','number')+field('city','Місто')+field('radius','Радіус роботи, км','number')+select('Доступність','availability',['Можу почати зараз','Через 2 тижні','Через місяць'])+`<label class="check"><input type="checkbox" name="nationwide" ${state.form.nationwide?'checked':''}/>Можу працювати по всій території Нідерландів</label>`+area('description','Короткий опис досвіду');if(i===3)body=upload('vca','Обов’язковий сертифікат VCA',true)+upload('certificates','Інші сертифікати')+upload('vehicle','Фото робочого автомобіля')+upload('portfolio','Фото виконаних робіт')+field('portfolio_url','Посилання на портфоліо','url',false);}
*/
const names=uk?['Про вас','Фото та VCA','Додатково','Перевірка']:['Bedrijf','Contactpersoon','Inzet & documenten','Controle'];let body='';const i=state.wizard;if(uk){if(i===0)body=field('name','Прізвище, ім’я та по батькові')+field('phone','Телефон','tel')+field('email','Email','email')+select('Вид діяльності','profession',jobs)+area('works','Перелік робіт',true)+field('experience_ua','Досвід роботи в Україні')+field('experience_nl','Досвід роботи в Нідерландах');if(i===1)body=upload('vca','Сертифікат VCA',true)+upload('portfolio','Фото виконаних робіт')+upload('tools','Фото інструментів')+upload('vehicle','Фото робочого автомобіля');if(i===2)body=`<p class="full muted">Усі поля на цьому кроці необов’язкові. Чим більше ви розкажете, тим швидше менеджер підбере для вас проєкт.</p>`+field('city','Місто','text',false)+field('radius_km','Радіус роботи, км','number',false)+field('hourly_rate','Ставка €/год','number',false)+optional('Доступність','availability',['Можу почати зараз','Через 2 тижні','Через місяць'])+optional('Мова спілкування','language',['Українська','Nederlands','English'])+`<label class="check full"><input type="checkbox" name="nationwide" ${state.form.nationwide?'checked':''}/>Можу працювати по всій території Нідерландів</label>`+field('company_name','Назва компанії','text',false)+field('kvk','Номер KVK (8 цифр)','text',false)+field('btw','Номер BTW','text',false)+field('address','Адреса реєстрації KVK','text',false)+field('website','Сайт','text',false)+field('instagram','Instagram','text',false)+field('facebook','Facebook','text',false)+field('tiktok','TikTok','text',false)+field('portfolio_url','Посилання на портфоліо','text',false)+field('extra_work','Додаткові види робіт','text',false)+area('description','Короткий опис досвіду')+upload('certificates','Інші сертифікати')+upload('portrait','Фото в робочому одязі');}/* Vorige bedrijfsaanmelding (vervangen door companyRegistration):
else{if(i===0)body=field('company_name','Bedrijfsnaam')+field('kvk','KVK-nummer (8 cijfers)')+field('btw','BTW-nummer')+field('address','Vestigingsadres')+field('website','Website','text',false)+area('description','Korte beschrijving van uw bedrijf');if(i===1)body=field('contact_name','Contactpersoon')+field('contact_role','Functie')+field('email','Zakelijk e-mailadres','email')+field('phone','Telefoonnummer','tel');if(i===2)body=field('region','Werkgebied')+select('Gewenste specialisatie','desired_profession',jobs)+field('expected_count','Verwacht aantal vakmensen','number')+select('SNA-certificering','sna',['Ja','Nee','In aanvraag'])+upload('company_docs','Bedrijfsdocumenten',true)+upload('certificates','Certificaten');}
*/if(i===names.length-1)body=`<div class="full"><h3>${uk?'Перевірте свій профіль':'Controleer uw registratie'}</h3>${Object.entries(state.form).filter(([k,v])=>FORM_LABELS[k]&&v!==''&&v!=='—'&&v!==false).map(([k,v])=>`<p><b>${esc(FORM_LABELS[k])}:</b> ${esc(v===true?(uk?'Так':'Ja'):v)}</p>`).join('')}<div class="note">${uk?'Клієнтам будуть доступні: спеціалізація, досвід, регіон, ставка, сертифікати та обезличені роботи. Особисті контакти захищені.':'Uw bedrijfsgegevens worden gecontroleerd door UHR. De gegevens van vakmensen blijven beschermd.'}</div><label class="check"><input name="consent" type="checkbox" required/>${uk?'Погоджуюся на обробку персональних даних':'Ik ga akkoord met de verwerking van mijn gegevens'} · <a href="#privacy">Privacy</a></label></div>`;return `${header()}<main class="wizard"><div class="eyebrow">${uk?'Ваш шлях до нових можливостей':'Uw eerste stap naar samenwerking'}</div><h1>${uk?'Професійний профіль':'Meld uw bedrijf aan.'}</h1><p>${uk?'Розкажіть про себе. Решту організуємо разом.':'Een zorgvuldig proces. Eén betrouwbare partner.'}</p><div class="progress">${names.map((n,j)=>`<div class="${j<=i?'active':''}">${j+1}. ${n}</div>`).join('')}</div><form id="wizard" class="card" data-last="${i===names.length-1}"><h3>${names[i]}</h3><div class="fields">${body}</div><div class="note">${uk?'Платіжні реквізити можна буде безпечно додати пізніше — після першої фактури.':'KVK: uw 8-cijferige inschrijving. BTW: uw omzetbelastingnummer. '}</div><div class="actions"><button type="button" data-back class="btn light">← ${uk?'Назад':'Terug'}</button><button class="btn">${i===names.length-1?(uk?'Надіслати на перевірку':'Registratie indienen'):(uk?'Продовжити →':'Volgende stap →')}</button></div></form></main>${footer()}`}
const googleMark=`<svg class="google-mark" viewBox="0 0 48 48" aria-hidden="true"><path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"/><path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z"/><path fill="#FBBC05" d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z"/><path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"/><path fill="none" d="M0 0h48v48H0z"/></svg>`;
const googleButton=()=>state.authConfig?.google?`<div class="full auth-google"><a class="google-btn" href="/api/v1/company/auth/google/start">${googleMark}<span>${tr('google.continue')}</span></a><div class="auth-or" role="separator"><span>${tr('google.orShort')}</span></div></div>`:'';
function companyStatus(){const c=state.account.company;const [title,text]={pending:[tr('reg.pendingTitle'),tr('reg.pendingText').replace('%s',esc(state.account.email))],approved:[tr('reg.approvedTitle'),tr('reg.approvedText')],clarification:[tr('reg.clarifyTitle'),c.admin_comment?esc(c.admin_comment):tr('reg.clarifyFallback')],rejected:[tr('reg.rejectedTitle'),c.admin_comment?esc(c.admin_comment):tr('reg.rejectedFallback')]}[c.status]||[tr('reg.receivedTitle'),''];return `${header()}<div class="wizard card empty"><div class="icon" style="margin:auto">${['pending','approved'].includes(c.status)?'✓':'!'}</div><h1>${title}</h1><p>${esc(c.company_name)} · ${tr('reg.application')} #${esc(c.id)}</p><p>${text}</p>${c.status==='approved'?btn(tr('login.workspace'),'overview'):btn(tr('reg.home'),'home')}</div>${footer()}`}
function snaNote(){if(state.snaBusy)return `<div class="note full">${tr('sna.busy')}</div>`;const s=state.sna;if(!s)return '';const r=s.register;let text;if(s.verified)text=`<b>✓ ${tr('sna.found')}</b><br>${esc(r.company_name)} · ${esc(r.address)} · KvK ${esc(s.kvk)}${r.activities?.length?'<br>'+r.activities.map(esc).join(' · '):''}`;else if(!s.kvk)text=tr('sna.noKvk');else if(!s.kvk_matches)text=tr('sna.mismatch').replace('%a',esc(s.extracted.kvk)).replace('%b',esc(s.kvk));else if(r?.found)text=`<b>${esc(r.company_name)} ${tr('sna.inRegister')}</b><br>${tr('sna.manualFile')}`;else if(r?.found===false)text=tr('sna.missing').replace('%s',esc(s.kvk));else text=tr('sna.registerDown');return `<div class="note full">${text}</div>`}
async function checkCertificate(){const file=state.files.sna?.[0];if(!file)throw new Error(tr('sna.needFile'));const body=new FormData();const upload=await shrinkImage(file);body.append('file',upload,upload.name);body.append('kvk',state.form.kvk||'');state.snaBusy=true;try{state.sna=await companyApi('sna/check',{method:'POST',body})}finally{state.snaBusy=false}const found=state.sna.register?.found?state.sna.register:{},read=state.sna.extracted||{};if(state.sna.kvk)state.form.kvk=state.sna.kvk;state.form.company_name=found.company_name||read.company_name||state.form.company_name||'';state.form.address=found.address||state.form.address||''}
function joinPlan(){const contractor=state.form.company_type==='contractor';const steps=contractor?['account','kind','certs','company','contact','check']:['account','kind','certs','contact','check'];const titles={account:tr('join.account'),kind:tr('join.kind'),certs:contractor?tr('join.certs'):state.form.company_type==='agency'?tr('join.cert'):tr('join.certStep'),company:tr('join.companyStep'),contact:tr('join.contact'),check:tr('join.check')};return {contractor,steps,titles}}
function companyRegistration(){if(state.account?.company)return companyStatus();const {contractor,steps,titles}=joinPlan();const labels={company_name:tr('join.company'),kvk:tr('join.kvk'),address:tr('join.address'),contact_name:tr('company.contact'),contact_role:tr('company.role'),phone:tr('company.phone'),website:tr('company.website'),description:tr('company.note')};const i=state.wizard=state.account?Math.max(1,Math.min(state.wizard,steps.length-1)):0;const step=steps[i];let body='',note='';if(step==='account'){body=googleButton()+field('email',tr('join.email'),'email',true,undefined,true)+field('password',tr('join.password'),'password',true,undefined,true)+field('password_repeat',tr('join.repeat'),'password',true,undefined,true)+`<p class="full muted">${tr('join.haveAccount')} <a href="#login">${tr('join.login')}</a></p>`;note=tr('join.accountNote')}if(step==='kind'){body=`<div class="kind-choices"><button type="button" class="kind-choice" data-kind="agency">${icon('users')}<strong>${tr('join.kindAgency')}</strong><span>${tr('join.kindAgencyText')}</span></button><button type="button" class="kind-choice" data-kind="contractor">${icon('hard-hat')}<strong>${tr('join.kindContractor')}</strong><span>${tr('join.kindContractorText')}</span></button></div>`;note=tr('join.kindLead')}if(step==='certs'&&contractor){body=upload('iso',tr('join.isoLabel'),true,false)+upload('vca',tr('join.vcaLabel'),true,false);note=tr('join.certsNote')}if(step==='certs'&&!contractor){body=upload('sna',tr('join.certLabel'),true,false)+snaNote()+(state.sna?field('company_name',tr('join.company'))+field('kvk',tr('join.kvk'))+field('address',tr('join.address'),'text',false):'');note=tr('join.certNote')}if(step==='company')body=field('company_name',tr('join.company'))+field('kvk',tr('join.kvk'))+field('address',tr('join.address'),'text',false);if(step==='contact')body=field('contact_name',tr('company.contact'))+field('contact_role',tr('company.role'),'text',false)+field('phone',tr('company.phone'),'tel')+field('website',tr('company.website'),'text',false)+area('description',tr('company.note'))+`<p class="full muted">${tr('join.emailLabel')}: ${esc(state.account.email)}</p>`;if(step==='check'){const certs=contractor?`<p><b>${tr('join.isoShort')}:</b> ${esc(state.files.iso?.[0]?.name||state.form.iso||'')}</p><p><b>VCA:</b> ${esc(state.files.vca?.[0]?.name||state.form.vca||'')}</p>`:`<p><b>${tr('join.certShort')}:</b> ${esc(state.files.sna?.[0]?.name||state.form.sna||'')} · ${state.sna?.verified?tr('join.verified'):tr('join.manual')}</p>`;body=`<div class="full"><h3>${tr('join.review')}</h3><p><b>${tr('join.kindTitle')}:</b> ${esc(contractor?tr('join.kindContractor'):tr('join.kindAgency'))}</p>${COMPANY_KEYS.filter(k=>k!=='company_type'&&state.form[k]).map(k=>`<p><b>${esc(labels[k]||k)}:</b> ${esc(state.form[k])}</p>`).join('')}<p><b>${tr('join.emailLabel')}:</b> ${esc(state.account.email)}</p>${certs}<div class="note">${tr('join.after')}</div><label class="check"><input name="consent" type="checkbox" required/>${tr('join.consent')} · <a href="#privacy">${tr('footer.privacy')}</a></label></div>`}const submit=step==='account'?tr('join.create'):step==='certs'&&!contractor&&!state.sna?tr('join.checkCert'):step==='check'?tr('join.submit'):tr('join.next');const actions=step==='kind'?'':`<div class="actions">${i>1?`<button type="button" data-back class="btn light">← ${tr('join.back')}</button>`:'<span></span>'}<button class="btn" data-label="${esc(submit)}">${submit}</button></div>`;return `${header()}<main class="wizard"><div class="eyebrow">${tr('join.eyebrow')}</div><h1>${tr('join.title')}</h1><p>${tr('join.lead')}</p><div class="progress">${steps.map((name,j)=>`<div class="${j<=i?'active':''}">${j+1}. ${titles[name]}</div>`).join('')}</div><form id="wizard" class="card" data-step="${i}"><h3>${step==='kind'?tr('join.kindTitle'):titles[step]}</h3><div class="fields">${body}</div>${note?`<div class="note">${note}</div>`:''}${actions}</form></main>${footer()}`}
async function companyStep(f){const i=state.wizard,button=f.querySelector('button:not([type="button"])');const busy=text=>{if(!button)return;button.disabled=true;button.textContent=text};try{const {contractor,steps}=joinPlan();const step=steps[i];if(step==='account'){const data=new FormData(f);if(data.get('password')!==data.get('password_repeat'))throw new Error(tr('login.mismatch'));busy(tr('join.creating'));state.form.email=data.get('email');state.account=await companyApi('auth/register',{method:'POST',body:JSON.stringify({email:data.get('email'),password:data.get('password')})});state.wizard=1;render();return}saveForm(f);if(step==='certs'&&!contractor&&(!state.sna||state.sna.kvk!==state.form.kvk)){busy(tr('join.checking'));await checkCertificate();render();return}if(step==='certs'&&contractor&&(!state.files.iso?.[0]||!state.files.vca?.[0]))throw new Error(!state.files.iso?.[0]?tr('iso.needFile'):tr('join.needVca'));if(i<steps.length-1){state.wizard++;render();return}busy(tr('join.sending'));const body=new FormData();body.append('data',JSON.stringify(applicationPayload()));if(contractor){const isoFile=await shrinkImage(state.files.iso[0]);const vcaFile=await shrinkImage(state.files.vca[0]);body.append('iso',isoFile,isoFile.name);body.append('vca',vcaFile,vcaFile.name)}else{const file=await shrinkImage(state.files.sna[0]);body.append('sna',file,file.name)}await companyApi('registration',{method:'POST',body});state.account=await companyApi('me');state.sna=null;state.files={};render()}catch(error){toast(error.message);if(button){button.disabled=false;button.textContent=button.dataset.label}}}
function requestForm(id){const w=workers.find(x=>x.id===Number(id));if(!w)return info('404');return shell(`<h1>${tr('req.title')}</h1><p>${tr('card.person')} #${w.id} · ${esc(jobName(w.job))} · ${w.rate?'€ '+w.rate+tr('profile.hour'):tr('card.rateAsk')}</p><form id="request-form" class="card"><div class="fields">${field('project',tr('req.project'),'text',true,'')+field('site_address',tr('req.address'),'text',false,'')+field('start',tr('req.start'),'date',false,'')+field('duration',tr('req.duration'),'text',false,'')+field('schedule',tr('req.schedule'),'text',false,'')+field('count',tr('req.count'),'number',false,'')+area('work',tr('req.work'),false,'')+area('requirements',tr('req.requirements'),false,'')}</div><div class="note">${tr('req.note')}</div><button class="btn" data-worker="${w.id}">${tr('req.send')}</button></form>`,'requests')}
function requestDetail(id){const r=requests.find(x=>x.id===id);if(!r)return info('404');const rows=[[tr('req.addressLabel'),r.site_address],[tr('req.durationLabel'),r.duration],[tr('req.scheduleLabel'),r.schedule],[tr('req.countLabel'),r.workers_count],[tr('req.workLabel'),r.work_description],[tr('req.requirementsLabel'),r.requirements]].filter(([,v])=>v);return shell(`<h1>${tr('table.request')} ${esc(r.id)}</h1><div class="card"><h3>${esc(r.project)}</h3><p>${esc(r.job?jobName(r.job):tr('req.tradeLater'))} · ${esc(nlDate(r.date))}</p><span class="badge ${r.status==='In behandeling'?'yellow':''}">${esc(statusName(r.status))}</span>${rows.map(([k,v])=>`<p><b>${k}:</b> ${esc(v)}</p>`).join('')}<div class="note">${tr('req.managerNote')}</div><div class="actions">${btn(tr('req.message'),'messages/'+r.id)}${r.worker?btn(tr('req.profile'),'profile/'+r.worker,'light'):''}</div></div>`,'requests')}
function messages(arg){if(!requests.length)return shell(`<h1>${tr('msg.title')}</h1><p>${tr('msg.lead')}</p><div class="card empty">${tr('msg.empty')}</div>`,'messages');const current=requests.find(r=>r.id===arg)||requests[0];const threadName=r=>r.project==='Selectie'?tr('select.thread'):r.project;const list=requests.map(r=>`<a href="#messages/${esc(r.id)}"><strong>${esc(threadName(r))}</strong><br><span class="muted">${esc(r.id)} · ${esc(statusName(r.status))}</span><p>${esc(r.last_message||tr('msg.none'))}</p></a>`).join('');const bubbles=(current.messages||[]).map(m=>`<div class="bubble ${m.sender_role==='company'?'mine':''}">${esc(m.body)}</div>`).join('')||`<p class="muted">${tr('msg.ask')}</p>`;const chosen=(current.selection||[]).map(w=>`<a href="#profile/${w.id}">#${w.id} ${esc(jobName(w.profession))} · ${esc(w.city||'')}</a>`).join('');const selection=chosen?`<div class="selection-people"><span>${tr('select.inThread')}</span>${chosen}</div>`:'';return shell(`<h1>${tr('msg.title')}</h1><p>${tr('msg.lead')}</p><div class="chat"><aside class="card">${list}</aside><div class="card"><h3>${esc(threadName(current))}</h3><div class="note">${esc(current.id)} · ${esc(current.job?jobName(current.job):tr('req.tradeLater'))} · ${esc(statusName(current.status))}</div>${selection}<div class="thread-log">${bubbles}</div><form id="chat-form" data-request="${esc(current.id)}" class="actions"><input name="message" aria-label="${tr('msg.label')}" placeholder="${tr('msg.placeholder')}" required style="flex:1"/><button class="btn">${tr('msg.send')}</button></form></div></div>`,'messages')}
function account(page){const p=companyProfile||{},docs=page==='documents',settingsPage=page==='settings';const docRows=(p.documents||[]).map(d=>`<tr><td>${esc(phrase(lang,d.kind_label))}</td><td>${esc(d.original_name)}</td><td><a class="btn light" href="${esc(d.url)}" target="_blank" rel="noopener">${tr('docs.view')}</a></td></tr>`).join('')||`<tr><td colspan="3">${tr('docs.empty')}</td></tr>`;const body=docs?`<div class="card table-scroll"><table><tr><th>${tr('docs.kind')}</th><th>${tr('docs.file')}</th><th></th></tr>${docRows}</table></div>`:settingsPage?`<div class="card"><h3>${tr('settings.title')}</h3><p>${tr('settings.text')}</p></div>`:`<form id="account-form" class="card"><div class="fields">${field('contact_name',tr('company.contact'),'text',true,p.contact_name)+field('contact_role',tr('company.role'),'text',false,p.contact_role)+field('phone',tr('company.phone'),'tel',true,p.phone)+field('website',tr('company.website'),'text',false,p.website)+field('address',tr('company.address'),'text',false,p.address)+area('description',tr('company.note'),false,p.description)}</div><p class="muted">${tr('company.firm')}: ${esc(p.company_name)} · KVK ${esc(p.kvk)} · ${esc(p.email)}. ${tr('company.fromCert')}</p><button class="btn" style="margin-top:25px">${tr('company.save')}</button></form>`;return shell(`<h1>${docs?tr('docs.title'):settingsPage?tr('settings.title'):tr('company.title')}</h1><p>${esc(p.company_name||'')} · ${tr('shell.verified')}${p.sna_verified?' · SNA':''}</p>${body}`,page)}
function login(reset=false,token=''){const approved=state.account?.company?.status==='approved';if(state.account&&!reset)return `${header()}<div class="wizard"><div class="card"><div class="eyebrow">${tr('login.eyebrow')}</div><h1>${tr('login.in')}</h1><p>${esc(state.account.email)}</p><div class="actions">${btn(approved?tr('login.workspace'):tr('login.application'),approved?'overview':'register')}<button type="button" class="btn light" data-logout>${tr('login.out')}</button></div></div></div>${footer()}`;const mode=token?'password':reset?'email':'';return `${header()}<div class="wizard"><div class="card"><div class="eyebrow">${tr('login.eyebrow')}</div><h1>${reset?tr('login.resetTitle'):tr('login.welcome')}</h1><p>${mode==='password'?tr('login.newPassword'):mode==='email'?tr('login.emailHelp'):tr('login.open')}</p><form id="login-form" data-reset="${mode}" data-token="${esc(token)}"><div class="fields">${mode?'':googleButton()}${mode==='password'?'':field('login_email',tr('login.email'),'email',true,undefined,true)}${mode==='email'?'':field('password',mode==='password'?tr('login.passwordNew'):tr('login.password'),'password',true,'',true)}${mode==='password'?field('password_repeat',tr('login.repeat'),'password',true,'',true):''}</div><button class="btn" style="margin:25px 0">${mode==='email'?tr('login.requestLink'):mode==='password'?tr('login.savePassword'):tr('login.submit')}</button></form><a href="#${reset?'login':'reset'}">${reset?tr('login.back'):tr('login.forgot')}</a></div></div>${footer()}`}
const faqUk=['Хто може зареєструватися?','Чи потрібна реєстрація KVK?','Чи обов’язковий VCA?','Хто побачить мої особисті дані?','Як я отримуватиму пропозиції?','Чи потрібно оплачувати реєстрацію?'];
function info(page){const titles={about:uk?'Про нас':tr('about.title'),contact:uk?'Зв’яжіться з нами':tr('contact.title'),privacy:uk?'Конфіденційність':tr('legal.title.privacy'),terms:uk?'Умови використання':tr('legal.title.terms'),cookies:uk?'Cookiebeleid':tr('legal.title.cookies'),faq:uk?'Поширені запитання':tr('faq.title'),pending:tr('reg.pendingTitle'),rejected:tr('reg.clarifyTitle'),'404':uk?'Сторінку не знайдено':tr('page.404')};let body='';if(page==='faq'){const qs=uk?faqUk:[1,2,3,4,5,6].map(n=>tr('faq.'+n));const as=uk?['Українські майстри та невеликі будівельні компанії, що працюють у Нідерландах.','В анкеті передбачено перевірку KVK менеджером.','Так, анкета містить обов’язкове завантаження VCA.','Менеджер бачить повну анкету. Компаніям доступний лише обезличений профіль.','Усі пропозиції та узгодження проходять через менеджера.','У прототипі оплата відсутня. Умови реєстрації будуть визначені перед запуском.']:[1,2,3,4,5,6].map(n=>tr('faq.'+n+'a'));body=qs.map((q,i)=>`<details><summary>${q}</summary><p>${as[i]}</p></details>`).join('')}else if(page==='contact')body=`<p>${uk?'Залиште повідомлення для менеджера.':tr('contact.lead')}</p><form id="contact-form"><div class="fields">${field('contact_name',uk?'Ваше ім’я':tr('contact.name'))+field('contact_email','Email','email')+area('message',uk?'Повідомлення':tr('contact.message'))}</div><button class="btn" style="margin-top:20px">${uk?'Надіслати':tr('contact.send')}</button></form>`;else if(page==='about'&&!uk)body=`<p>${tr('about.body')}</p><div class="note">${tr('about.note')}</div>`+btn(tr('nav.register'),'register');else if(page==='about')body='<p>Ukrwerkspot збирає професійні профілі майстрів для роботи в Нідерландах.</p>';else if(page==='pending'||page==='rejected')body=`<p>${page==='pending'?tr('info.pendingBody'):tr('info.rejectedBody')}</p>${page==='rejected'?upload('replacement',tr('info.updateDoc'))+`<button class="btn" data-toast="${esc(tr('info.docLocal'))}">${tr('info.resubmit')}</button>`:btn(tr('page.home'),'home')}`;else if(page==='404')body=btn(uk?'На головну':tr('page.home'),'home');else body=`<div class="note">${uk?'Остаточний юридичний текст буде додано до запуску.':tr('legal.sample')}</div><h3>${uk?'Обробка даних':tr('legal.use')}</h3><p>${uk?'Цей прототип не надсилає форми, не створює облікові записи та не обробляє платежі. Введені дані існують лише в пам’яті поточного перегляду.':tr('legal.p1')}</p><p>${uk?'Зовнішні зображення та шрифт можуть завантажуватися зі сторонніх сервісів.':tr('legal.p2')}</p>`;return `${header()}<main class="legal"><h1>${titles[page]||titles['404']}</h1>${body}</main>${footer()}`}
function adminPage(page){if(page==='requests')return requestsPage();if(page==='messages')return messages();const master=page==='masters',company=page==='companies';return shell(`<div class="eyebrow">Єдина екосистема · два домени</div><h1>${master?'Перевірка майстрів':company?'Перевірка компаній':'Центр управління UHR'}</h1><p>Ukrwerkspot → перевірка менеджером → обезличений каталог UHR → заявка компанії.</p>${!master&&!company?`<div class="stats">${[['Нові анкети','8'],['Компанії на перевірці','3'],['Активні заявки',requests.length],['Опубліковані профілі','48']].map(([a,b])=>`<div class="card">${a}<strong>${b}</strong>Overzicht</div>`).join('')}</div><div class="grid"><a class="card" href="#masters"><h3>Анкети Ukrwerkspot ↗</h3><p>Перевірка VCA та професійного досвіду.</p></a><a class="card" href="#companies"><h3>Компанії UHR ↗</h3><p>Перевірка юридичних даних та документів.</p></a><a class="card" href="#requests"><h3>Заявки ↗</h3><p>Планування та узгодження з компаніями.</p></a></div>`:`<div class="card table-scroll"><table><tr><th>ID</th><th>${master?'Спеціалізація':'Компанія'}</th><th>Джерело</th><th>Документи</th><th>Статус</th><th>Дії</th></tr>${(master?workers.slice(0,4):[{id:201,job:'Bouwbedrijf Parkzicht B.V.'},{id:202,job:'Voorbeeld Renovatie B.V.'},{id:203,job:'Projectbouw Noord B.V.'}]).map(w=>`<tr><td>#${w.id}</td><td>${w.job}</td><td>${master?'Ukrwerkspot':'UHR'}</td><td><button class="btn light" data-toast="Перегляд: документи на перевірці.">Переглянути</button></td><td><span class="badge ${state.approved.has(w.id)?'':'yellow'}">${state.approved.has(w.id)?'Схвалено':'На перевірці'}</span></td><td><button class="btn" data-approve="${w.id}">Схвалити</button> <button class="btn light" data-toast="запит на оновлення документів підготовлено.">Уточнити</button></td></tr>`).join('')}</table></div><div class="note">${master?'Після реальної перевірки публікується лише професійний профіль без імені та контактів.':'Після перевірки компанія отримає доступ до каталогу. У прототипі авторизація відсутня.'}</div>`}` ,page)}
function render(){const [page='home',arg]=(location.hash.slice(1)||'home').split('/');if(!uk&&!admin&&['overview','catalog','favorites','profile','request','requests','request-detail','messages','orders','company','documents','settings'].includes(page)&&state.account?.company?.status!=='approved'){location.hash=state.account?'register':'login';return}if(admin&&page!=='home')app.innerHTML=adminPage(page);else if(admin)app.innerHTML=adminPage('overview');else if(page==='home')app.innerHTML=landing();else if(page==='register')app.innerHTML=registration();else if(page==='overview')app.innerHTML=overview();else if(page==='catalog'||page==='favorites')app.innerHTML=catalog(page==='favorites',arg);else if(page==='profile')app.innerHTML=profile(arg);else if(page==='request')app.innerHTML=requestForm(arg);else if(page==='requests')app.innerHTML=selectionPage(arg==='contact');else if(page==='orders')app.innerHTML=ordersPage();else if(page==='messages')app.innerHTML=messages(arg);else if(['company','documents','settings'].includes(page))app.innerHTML=account(page);else if(page==='login'||page==='reset')app.innerHTML=login(page==='reset',arg||'');else if(page==='request-detail')app.innerHTML=requestDetail(arg);else app.innerHTML=info(page);filterCards();icons();const log=document.querySelector('.thread-log');if(log)log.scrollTop=log.scrollHeight;if(arg&&page==='home')document.getElementById(arg)?.scrollIntoView({behavior:'smooth'});else if(page!=='messages')window.scrollTo(0,0);}
function toast(text){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=uk?text:phrase(lang,text);document.body.append(el);setTimeout(()=>el.remove(),4000)}
function saveForm(form){for(const el of form.elements){if(!el.name||el.type==='submit')continue;if(el.type==='file'){if(el.files.length){state.files[el.name]=Array.from(el.files);state.form[el.name]=state.files[el.name].map(f=>f.name).join(', ')}}else state.form[el.name]=el.type==='checkbox'?el.checked:el.value}}
app.addEventListener('click',async e=>{const section=e.target.closest('[data-section]');if(section){e.preventDefault();document.getElementById(section.dataset.section)?.scrollIntoView({behavior:'smooth'});return}const kindBtn=e.target.closest('[data-kind]');if(kindBtn){e.preventDefault();const next=kindBtn.dataset.kind;if(state.form.company_type&&state.form.company_type!==next){state.sna=null;delete state.files.sna;delete state.files.iso;delete state.files.vca;state.form.sna='';state.form.iso='';state.form.vca=''}state.form.company_type=next;state.wizard=2;render();return}const t=e.target.closest('[data-pick],[data-fav],[data-back],[data-toast],[data-filter-toggle],[data-reset],[data-approve],[data-logout]');if(!t)return;if(t.hasAttribute('data-logout')){e.preventDefault();companyApi('auth/logout',{method:'POST'}).catch(()=>{});state.account=null;state.wizard=0;state.sna=null;state.form={};state.files={};requests=[];companyProfile=null;state.favorites=new Set();state.picks=new Set();companySource?.close();companySource=null;location.hash='home';render();return}if(t.dataset.pick){const id=Number(t.dataset.pick);try{const data=await companyApi('picks/'+id,{method:'POST'});state.picks=new Set(data.ids||[])}catch(error){toast(error.message);return}if(location.hash.startsWith('#requests')){render();return}const on=state.picks.has(id);document.querySelectorAll('[data-pick="'+id+'"]').forEach(btn=>{btn.classList.toggle('saved',on);btn.setAttribute('aria-pressed',String(on));const label=btn.classList.contains('labeled')?`<span>${tr('card.select')}</span>`:'';btn.innerHTML=icon(on?'check':'square')+label});icons();return}if(t.dataset.fav){const id=Number(t.dataset.fav);try{const data=await companyApi('favorites/'+id,{method:'POST'});state.favorites=new Set(data.ids)}catch(error){toast(error.message);return}const saved=state.favorites.has(id);document.querySelectorAll('[data-fav="'+id+'"]').forEach(btn=>{btn.classList.toggle('saved',saved);btn.setAttribute('aria-pressed',String(saved))});icons();if(location.hash.startsWith('#favorites'))filterCards()}if(t.hasAttribute('data-back')){saveForm(document.querySelector('#wizard'));state.wizard=Math.max(0,state.wizard-1);render()}if(t.dataset.toast)toast(t.dataset.toast);if(t.hasAttribute('data-filter-toggle')){const opened=document.querySelector('.filters').classList.toggle('open');document.querySelectorAll('[data-filter-toggle]').forEach(b=>b.setAttribute('aria-expanded',String(opened)))}if(t.hasAttribute('data-reset')){document.querySelectorAll('.filters select').forEach(s=>s.selectedIndex=0);document.querySelector('#rate').value='';document.querySelector('#search').value='';filterCards()}if(t.dataset.approve){state.approved.add(Number(t.dataset.approve));render();toast('Статус оновлено.')}});
app.addEventListener('input',e=>{if(e.target.closest('.catalog')||e.target.id==='search')filterCards();const blankOptional=!e.target.required&&e.target.value==='';if(e.target.name==='kvk')e.target.setCustomValidity(blankOptional||/^\d{8}$/.test(e.target.value)?'':uk?'KVK має містити 8 цифр':tr('kvk.invalid'));if(e.target.type==='number')e.target.setCustomValidity(blankOptional||Number(e.target.value)>0?'':uk?'Введіть число більше нуля':tr('number.invalid'));});
app.addEventListener('change',async e=>{if(e.target.type==='file')e.target.parentElement.querySelector('[data-files]').textContent=Array.from(e.target.files).map(f=>f.name).join(', ');if(e.target.name==='sna'&&e.target.files.length){saveForm(e.target.form);state.sna=null;state.form.kvk='';state.snaBusy=true;render();try{await checkCertificate()}catch(error){toast(error.message)}render();return}if(e.target.id==='request-status'){const value=e.target.value;document.querySelectorAll('tbody tr').forEach(row=>row.hidden=value!==''&&row.dataset.status!==value)}if(e.target.classList.contains('language')){if(uk){toast('Цей прототип представлено українською. Інші мови буде підключено пізніше.');return}lang=e.target.value==='en'?'en':'nl';try{localStorage.setItem('uhr-lang',lang)}catch{}applyLang();render()}});
app.addEventListener('dragover',e=>{if(e.target.closest('[data-drop]'))e.preventDefault()});app.addEventListener('drop',e=>{const drop=e.target.closest('[data-drop]');if(!drop)return;e.preventDefault();const input=drop.querySelector('input');input.files=e.dataTransfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));});
app.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(f.id==='wizard'&&!uk){await companyStep(f);return}if(f.id==='wizard'){saveForm(f);if(f.dataset.last!=='true'){state.wizard++;render();return}const button=f.querySelector('button:not([type="button"])');button.disabled=true;button.textContent=uk?'Надсилаємо…':'Bezig met verzenden…';try{state.submitted=await submitApplication();render()}catch(error){toast(error.message);button.disabled=false;button.textContent=uk?'Надіслати на перевірку':'Registratie indienen'}}else if(f.id==='login-form'){const data=new FormData(f);try{if(f.dataset.reset==='email'){await companyApi('auth/forgot',{method:'POST',body:JSON.stringify({email:data.get('login_email')})});toast(tr('login.sent'));return}if(f.dataset.reset==='password'){if(data.get('password')!==data.get('password_repeat'))throw new Error(tr('login.mismatch'));state.account=await companyApi('auth/reset',{method:'POST',body:JSON.stringify({token:f.dataset.token,password:data.get('password')})})}else{state.account=await companyApi('auth/login',{method:'POST',body:JSON.stringify({email:data.get('login_email'),password:data.get('password')})})}await loadCabinet();startCompanyInbox();location.hash=state.account.company?.status==='approved'?'overview':'register'}catch(error){toast(error.message)}}else if(f.id==='request-form'){const data=new FormData(f),w=workers.find(x=>x.id===Number(f.querySelector('[data-worker]').dataset.worker));const count=Number(data.get('count'));try{const item=await companyApi('requests',{method:'POST',body:JSON.stringify({craftsman_id:w.id,project:data.get('project'),site_address:data.get('site_address')||'',start_date:data.get('start')||null,duration:data.get('duration')||'',schedule:data.get('schedule')||'',workers_count:count>0?count:null,work_description:data.get('work')||'',requirements:data.get('requirements')||''})});requests.unshift(item);location.hash='requests';toast(tr('req.sent'))}catch(error){toast(error.message)}}else if(f.id==='selection-form'){const channel=e.submitter?.value||'chat';try{const item=await companyApi('selection/contact',{method:'POST',body:JSON.stringify({body:'',channel})});const row=requests.find(r=>r.id===item.id);if(row)Object.assign(row,item);else requests.unshift(item);state.picks=new Set();location.hash='messages/'+item.id;toast(item.emailed?tr('select.emailed'):tr('select.sent'));render()}catch(error){toast(error.message)}}else if(f.id==='chat-form'){try{const item=await companyApi('requests/'+encodeURIComponent(f.dataset.request)+'/messages',{method:'POST',body:JSON.stringify({body:new FormData(f).get('message')})});const row=requests.find(r=>r.id===item.id);if(row)Object.assign(row,item);render()}catch(error){toast(error.message)}}else if(f.id==='account-form'){const data=new FormData(f);try{companyProfile=await companyApi('profile',{method:'PUT',body:JSON.stringify({contact_name:data.get('contact_name'),contact_role:data.get('contact_role')||'',phone:data.get('phone'),website:data.get('website')||'',address:data.get('address')||'',description:data.get('description')||''})});toast(tr('company.saved'));render()}catch(error){toast(error.message)}}else toast(uk?'Дані не надсилаються.':tr('notSent'));});
let companySource=null,companyAudio=null,companyHeard=new Set();
function armCompanySound(){const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx)return;if(!companyAudio)companyAudio=new Ctx();if(companyAudio.state==='suspended')companyAudio.resume()}
function playCompanyPing(){armCompanySound();if(!companyAudio||companyAudio.state!=='running')return;const now=companyAudio.currentTime,osc=companyAudio.createOscillator(),gain=companyAudio.createGain();osc.type='sine';osc.frequency.setValueAtTime(880,now);osc.frequency.setValueAtTime(1175,now+.14);gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(.07,now+.02);gain.gain.exponentialRampToValueAtTime(.0001,now+.32);osc.connect(gain);gain.connect(companyAudio.destination);osc.start(now);osc.stop(now+.34)}
function applyLiveMessage(data){const row=requests.find(item=>item.id===data.public_id);if(!row)return false;row.messages=row.messages||[];if(row.messages.some(item=>item.id===data.message_id))return true;row.messages.push({id:data.message_id,sender_role:data.sender_role,body:data.body,created_at:new Date().toISOString()});row.last_message=data.body;return true}
function startCompanyInbox(){if(uk||admin||companySource||state.account?.company?.status!=='approved')return;document.addEventListener('pointerdown',armCompanySound,{once:true});const source=new EventSource('/api/v1/company/messages/stream');companySource=source;source.onmessage=async event=>{let data;try{data=JSON.parse(event.data)}catch{return}if(data.type!=='message'||(data.sender_role!=='admin'&&data.sender_role!=='company')||companyHeard.has(data.message_id))return;companyHeard.add(data.message_id);if(data.sender_role==='admin')playCompanyPing();if(!applyLiveMessage(data)){await loadCabinet();applyLiveMessage(data)}const [page,arg]=(location.hash.slice(1)||'').split('/');const openId=arg||requests[0]?.id;const field=document.querySelector('#chat-form [name=message]');const draft=field?.value||'';if(page==='messages'&&String(openId)===String(data.public_id)){render();const area=document.querySelector('#chat-form [name=message]');if(area&&draft)area.value=draft;return}if(data.sender_role==='admin')toast(tr('msg.incoming'))}}
if(!uk&&!admin&&state.account?.company?.status==='approved')startCompanyInbox();
window.addEventListener('hashchange',render);render();



